import { Metadata } from "next";
import { prisma } from "@/lib/prisma";
import PartnerCarousel from "@/components/PartnerCarousel";
import WaveHeader from "@/components/WaveHeader";

export const metadata: Metadata = {
    title: "100 Жилийн Ой — Түүхэн замнал | МҮЗХ",
    description: "Монголын Үндэсний Зуслангуудын Холбооны 100 жилийн түүхэн замнал (1926-2026)",
};

export const dynamic = "force-dynamic";

export default async function AnniversaryPage() {
    const dbSettings = await prisma.siteSetting.findMany({
        where: {
            key: {
                in: [
                    'anniversary_video_url',
                    'anniversary_hero_title',
                    'anniversary_hero_text',
                    'anniversary_accordions',
                ]
            }
        }
    });

    const sm = dbSettings.reduce((acc, curr) => {
        acc[curr.key] = curr.value;
        return acc;
    }, {} as Record<string, string>);

    const videoUrl = sm['anniversary_video_url'] || "https://www.youtube.com/embed/A6XUVjK9W4o";
    const heroTitle = sm['anniversary_hero_title'] || "Зууны Нөлөөлөл (1926–2026)";
    const heroText = sm['anniversary_hero_text'] || "Монголын Үндэсний Зуслангийн Холбооны 100 жилийн ойг угтаж түүхэн замналаа эргэн дурсаж байна.";

    // Fetch Timeline Events from database
    const timeline = await prisma.timelineEvent.findMany({
        where: { isActive: true },
        orderBy: { order: "asc" }
    });

    // Research posts
    const researchPosts = await prisma.post.findMany({
        where: { type: "RESEARCH", published: true },
        orderBy: { createdAt: "desc" },
    });

    // Accordions
    let accordions: any[] = [];
    try {
        accordions = JSON.parse(sm['anniversary_accordions'] || "[]");
    } catch (e) {}

    return (
        <div className="flex flex-col min-h-screen bg-slate-50 font-sans text-[#0F1B3D]">
            <WaveHeader title="ТҮҮХТ 100 ЖИЛИЙН ОЙ" />

            <section className="relative py-16">
                <div className="container mx-auto px-4 md:px-6 relative z-10">
                    {/* VIDEO HERO SECTION */}
                    <div className="mb-20 text-center max-w-4xl mx-auto space-y-6">
                        <div className="mx-auto rounded-[3rem] overflow-hidden shadow-2xl border-8 border-white bg-black aspect-video relative group">
                            {/* Golden Seal inside Video */}
                            <div className="absolute top-6 left-6 z-20 w-24 h-24 bg-gradient-to-br from-[#F5C542] to-[#D4A843] rounded-full flex flex-col items-center justify-center p-2 shadow-lg border-2 border-white/40 rotate-12 group-hover:rotate-0 transition-transform">
                                <span className="text-[#0F1B3D] text-[10px] font-black uppercase tracking-widest leading-none">MYC</span>
                                <span className="text-white text-3xl font-black leading-none my-1">100</span>
                                <span className="text-[#0F1B3D] text-[10px] font-black uppercase tracking-widest leading-none">YEARS</span>
                            </div>

                            <iframe
                                className="w-full h-full relative z-10"
                                src={videoUrl}
                                title="100 Жилийн Ойн Танилцуулга"
                                frameBorder="0"
                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                                allowFullScreen
                            />
                        </div>

                        <h2 className="text-3xl font-black">
                            {heroText}
                        </h2>
                    </div>

                    {/* TIMELINE TITLE */}
                    <div className="text-center mb-16">
                        <div className="inline-flex items-center gap-2 bg-[#F5C542]/10 text-[#D4A843] px-5 py-2 rounded-full font-bold uppercase tracking-widest mb-4 border border-[#F5C542]/20 shadow-sm shadow-[#F5C542]/10">
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" /></svg>
                            Түүхэн замнал
                        </div>
                    </div>

                    {/* TIMELINE COMPONENT */}
                    <div className="relative max-w-5xl mx-auto">
                        {/* Golden Center Line */}
                        <div className="absolute left-12 md:left-1/2 top-0 bottom-0 w-1 bg-gradient-to-b from-[#F5C542]/0 via-[#F5C542] to-[#F5C542]/0 -translate-x-1/2 rounded-full" />

                        <div className="space-y-16">
                            {timeline.length > 0 ? timeline.map((event, index) => (
                                <div key={event.id} className={`relative flex items-center w-full ${index % 2 === 0 ? 'md:flex-row-reverse' : 'md:flex-row'} flex-row justify-end md:justify-center`}>
                                    
                                    {/* Golden Dot */}
                                    <div className="absolute left-12 md:left-1/2 -translate-x-1/2 w-6 h-6 rounded-full bg-white border-4 border-[#F5C542] shadow-[0_0_15px_rgba(245,197,66,0.5)] z-10 flex items-center justify-center">
                                        <div className="w-1.5 h-1.5 rounded-full bg-[#0F1B3D]" />
                                    </div>

                                    {/* Year indicator pointing to dot */}
                                    <div className={`absolute left-20 md:left-auto md:w-0 w-auto ${index % 2 === 0 ? 'md:right-1/2 md:pr-10 md:text-right' : 'md:left-1/2 md:pl-10 md:text-left'} -mt-8 md:mt-0 font-black text-3xl md:text-5xl text-[#0F1B3D]/10 z-0 select-none`}>
                                        {event.year}
                                    </div>

                                    {/* Content Card */}
                                    <div className={`w-[calc(100%-80px)] md:w-[45%] ${index % 2 === 0 ? 'md:pl-10' : 'md:pr-10'} relative z-10`}>
                                        <div className="bg-white rounded-3xl p-6 shadow-[0_10px_30px_-15px_rgba(0,0,0,0.1)] border border-slate-100 hover:shadow-xl hover:-translate-y-1 transition-all">
                                            {/* Image/Video inside card */}
                                            {(event.imageUrl || event.videoUrl) && (
                                                <div className="relative aspect-video w-full rounded-xl overflow-hidden mb-5">
                                                    {event.videoUrl ? (
                                                        <iframe className="w-full h-full" src={event.videoUrl} frameBorder="0" allowFullScreen />
                                                    ) : (
                                                        <img src={event.imageUrl!} alt={event.title} className="w-full h-full object-cover" />
                                                    )}
                                                </div>
                                            )}

                                            <div className="flex items-center gap-3 mb-3">
                                                <div className="bg-[#0F1B3D] text-[#F5C542] text-xs font-black uppercase px-3 py-1 rounded-full whitespace-nowrap">
                                                    {event.year}
                                                </div>
                                                <h3 className="text-xl font-black text-[#0F1B3D] leading-tight">
                                                    {event.title}
                                                </h3>
                                            </div>

                                            {event.description && (
                                                <p className="text-slate-500 font-medium text-sm leading-relaxed">
                                                    {event.description}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            )) : (
                                <div className="text-center py-20 text-slate-400 font-medium">
                                    Түүхэн замналын мэдээлэл одоогоор алга байна.
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </section>
        </div>
    );
}
